import{_ as e,o as a,c as r,an as i}from"./chunks/framework.CliSN-dr.js";const y=JSON.parse('{"title":"The packages","description":"","frontmatter":{},"headers":[],"relativePath":"packages.md","filePath":"packages.md","lastUpdated":null}'),l={name:"packages.md"};function o(s,t,h,d,n,g){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="The-packages" tabindex="-1">The packages <a class="header-anchor" href="#The-packages" aria-label="Permalink to &quot;The packages {#The-packages}&quot;">​</a></h1><p>The ecosystem separates the problem by discipline: physics packages for the environment, organism-level packages for heat exchange, behaviour and metabolism, and Mapper packages that run them over forcing data at points or across landscapes. The <a href="/NicheMapper.jl/dev/architecture/mechanistic_niche_modelling_framework#Dependencies">dependency graph</a> shows how they build on each other.</p><h2 id="Physical-environment" tabindex="-1">Physical environment <a class="header-anchor" href="#Physical-environment" aria-label="Permalink to &quot;Physical environment {#Physical-environment}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Package</th><th style="text-align:right;">What it provides</th><th style="text-align:right;">Docs</th></tr></thead><tbody><tr><td style="text-align:right;">Microclimate.jl</td><td style="text-align:right;">Soil, surface, snow and canopy energy and water balance; hourly microclimate profiles for one site</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/Microclimate.jl/dev/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td style="text-align:right;">MicroclimateMapper.jl</td><td style="text-align:right;">Microclimate.jl over points and grids, from weather, terrain, soil and land cover data sets</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/MicroclimateMapper.jl/dev/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td style="text-align:right;">SolarRadiation.jl</td><td style="text-align:right;">Solar geometry and spectral direct, diffuse and global irradiance</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/SolarRadiation.jl/previews/PR21/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td style="text-align:right;">FluidProperties.jl</td><td style="text-align:right;">Properties of air, water vapour and liquid water</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/FluidProperties.jl/dev/" target="_blank" rel="noreferrer">docs</a></td></tr></tbody></table><h2 id="Organisms" tabindex="-1">Organisms <a class="header-anchor" href="#Organisms" aria-label="Permalink to &quot;Organisms {#Organisms}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Package</th><th style="text-align:right;">What it provides</th><th style="text-align:right;">Docs</th></tr></thead><tbody><tr><td style="text-align:right;">HeatExchange.jl</td><td style="text-align:right;">Heat and water budgets of organisms (radiation, convection, evaporation, conduction); body and leaf temperature</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/HeatExchange.jl/previews/PR57/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td style="text-align:right;">BiophysicalGeometry.jl</td><td style="text-align:right;">Body shapes and insulation (fur, feathers, fat)</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/BiophysicalGeometry.jl/previews/PR20/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td style="text-align:right;">BiophysicalBehaviour.jl</td><td style="text-align:right;">Thermoregulation of ectotherms, endotherms and heterotherms; activity; optimal control</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/BiophysicalBehaviour.jl/previews/PR28/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td style="text-align:right;">ThermalPhysiology.jl</td><td style="text-align:right;">Thermal performance curves, temperature corrections, thermal death time and tolerance landscapes</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/ThermalPhysiology.jl/dev/" target="_blank" rel="noreferrer">docs</a></td></tr></tbody></table><h2 id="Metabolism" tabindex="-1">Metabolism <a class="header-anchor" href="#Metabolism" aria-label="Permalink to &quot;Metabolism {#Metabolism}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Package</th><th style="text-align:right;">What it provides</th><th style="text-align:right;">Docs</th></tr></thead><tbody><tr><td style="text-align:right;">DEBtool_J.jl</td><td style="text-align:right;">Dynamic Energy Budget models of full life cycles, from the Add-my-Pet collection</td><td style="text-align:right;"><a href="https://add-my-pet.github.io/DEBtool_J.jl/" target="_blank" rel="noreferrer">docs</a></td></tr><tr><td style="text-align:right;">BiologicalScaling.jl</td><td style="text-align:right;">Allometry of metabolic rate, geometry and life history across taxa</td><td style="text-align:right;"><a href="https://biophysicalecology.github.io/BiologicalScaling.jl/dev/" target="_blank" rel="noreferrer">docs</a></td></tr></tbody></table><h2 id="Mapper-packages" tabindex="-1">Mapper packages <a class="header-anchor" href="#Mapper-packages" aria-label="Permalink to &quot;Mapper packages {#Mapper-packages}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Package</th><th style="text-align:right;">What it provides</th><th style="text-align:right;">Status</th></tr></thead><tbody><tr><td style="text-align:right;">AnimalMapper.jl</td><td style="text-align:right;">Animal heat budgets, behaviour and metabolism over mapped microclimates</td><td style="text-align:right;">planned</td></tr><tr><td style="text-align:right;">PlantMapper.jl</td><td style="text-align:right;">Plant heat and water budgets, photosynthesis and growth, coupled to the microclimate</td><td style="text-align:right;">planned</td></tr><tr><td style="text-align:right;">MicrobeMapper.jl</td><td style="text-align:right;">Microbial growth driven by soil temperature and moisture</td><td style="text-align:right;">planned</td></tr><tr><td style="text-align:right;">NicheMapper.jl</td><td style="text-align:right;">Installs the whole ecosystem</td><td style="text-align:right;">this package</td></tr></tbody></table><p>BiophysicalEcologyBase.jl holds the abstract types the packages share.</p><h2 id="Where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#Where-to-start" aria-label="Permalink to &quot;Where to start {#Where-to-start}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">I want to…</th><th style="text-align:right;">Start with</th></tr></thead><tbody><tr><td style="text-align:right;">map microclimates, or derive gridded predictors for distribution models</td><td style="text-align:right;">MicroclimateMapper.jl</td></tr><tr><td style="text-align:right;">run a detailed microclimate at one site, or test its physics</td><td style="text-align:right;">Microclimate.jl</td></tr><tr><td style="text-align:right;">compute the temperature of an animal or leaf in a given environment</td><td style="text-align:right;">HeatExchange.jl</td></tr><tr><td style="text-align:right;">interpret body temperature, metabolic or water-loss data</td><td style="text-align:right;">HeatExchange.jl, ThermalPhysiology.jl</td></tr><tr><td style="text-align:right;">simulate thermoregulation and activity</td><td style="text-align:right;">BiophysicalBehaviour.jl</td></tr><tr><td style="text-align:right;">simulate growth, reproduction and life history</td><td style="text-align:right;">DEBtool_J.jl</td></tr></tbody></table><p>The <a href="/NicheMapper.jl/dev/architecture/mechanistic_niche_modelling_framework#Use-cases">Architecture overview</a> lists the use cases the ecosystem is designed around.</p>',14)])])}const p=e(l,[["render",o]]);export{y as __pageData,p as default};
